import React, { useState } from 'react';
import { gql, useQuery, useMutation } from '@apollo/client';

// ============================================================
// HELPER
// ============================================================
function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return '—';
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, '0');
  return `${m}:${s}`;
}

// ============================================================
// QUERIES & MUTATIONS
// ============================================================
const ALBUMS_QUERY = gql`
  query Albums($page: Int, $limit: Int) {
    albums(page: $page, limit: $limit) {
      nodes {
        id
        title
        artist {
          id
          name
        }
        release_date
        genre_id
        nb_tracks
        cover_medium
      }
      totalCount
      pageInfo {
        hasNextPage
        hasPreviousPage
        currentPage
        totalPages
      }
    }
  }
`;

const ALBUM_DETAIL_QUERY = gql`
  query Album($id: ID!) {
    album(id: $id) {
      id
      title
      release_date
      genre_id
      label
      nb_tracks
      tracks {
        id
        title
        duration
        position
        explicit_lyrics
      }
    }
  }
`;

const CREATE_ALBUM_MUTATION = gql`
  mutation CreateAlbum($input: CreateAlbumInput!) {
    createAlbum(input: $input) {
      id
      title
      artist {
        name
      }
    }
  }
`;

const DELETE_ALBUM_MUTATION = gql`
  mutation DeleteAlbum($id: ID!) {
    deleteAlbum(id: $id) {
      success
    }
  }
`;

const ARTISTS_LIST_QUERY = gql`
  query Artists {
    artists(limit: 100) {
      nodes {
        id
        name
      }
    }
  }
`;

// ============================================================
// COMPOSANT
// ============================================================
export default function Albums({ token, userRole }) {
  const [page, setPage] = useState(1);
  const [showForm, setShowForm] = useState(false);
  const [selectedAlbum, setSelectedAlbum] = useState(null);
  const [formData, setFormData] = useState({
    title:        '',
    artistId:     '',
    release_date: '',
    genre_id:     '',
    label:        '',
  });
  const [error, setError]     = useState('');
  const [success, setSuccess] = useState('');

  const authHeaders = { context: { headers: { authorization: `Bearer ${token}` } } };

  const { data, loading, error: queryError, refetch } = useQuery(ALBUMS_QUERY, {
    variables: { page, limit: 6 },
    ...authHeaders,
  });

  const { data: artistsData } = useQuery(ARTISTS_LIST_QUERY, authHeaders);

  const { data: albumDetail, loading: albumDetailLoading } = useQuery(ALBUM_DETAIL_QUERY, {
    variables: { id: selectedAlbum },
    skip: !selectedAlbum,
    ...authHeaders,
  });

  const [createAlbum, { loading: createLoading }] = useMutation(CREATE_ALBUM_MUTATION, {
    ...authHeaders,
    onCompleted: () => {
      setSuccess('Album créé !');
      setFormData({ title: '', artistId: '', release_date: '', genre_id: '', label: '' });
      setShowForm(false);
      refetch();
    },
    onError: (err) => setError(err.message),
  });

  const [deleteAlbum] = useMutation(DELETE_ALBUM_MUTATION, {
    ...authHeaders,
    onCompleted: () => { setSuccess('Album supprimé !'); refetch(); },
    onError: (err) => setError(err.message),
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    createAlbum({
      variables: {
        input: {
          title:        formData.title,
          artistId:     formData.artistId,
          release_date: formData.release_date || undefined,
          genre_id:     formData.genre_id ? parseInt(formData.genre_id, 10) : undefined,
          label:        formData.label || undefined,
        },
      },
    });
  };

  if (loading)     return <div className="loading">⏳ Chargement des albums...</div>;
  if (queryError)  return <div className="error">❌ Erreur : {queryError.message}</div>;

  const albums   = data?.albums?.nodes   || [];
  const pageInfo = data?.albums?.pageInfo || {};

  // ---- Vue détail ----
  if (selectedAlbum) {
    const album = albumDetail?.album;
    return (
      <div>
        <button onClick={() => setSelectedAlbum(null)} className="btn-secondary">
          ← Retour
        </button>

        {albumDetailLoading && <div className="loading">⏳ Chargement...</div>}

        {album && (
          <div className="card" style={{ maxWidth: '100%', marginTop: '1rem' }}>
            <h3>{album.title}</h3>
            <div className="card-meta">
              {album.release_date && (
                <span>📅 {new Date(album.release_date).getFullYear()}</span>
              )}
              <span>🎵 {album.nb_tracks ?? 0} piste{album.nb_tracks > 1 ? 's' : ''}</span>
              {album.genre_id && <span>🏷️ Genre #{album.genre_id}</span>}
              {album.label    && <span>🎙️ {album.label}</span>}
            </div>

            <h4 style={{ marginTop: '2rem', marginBottom: '1rem' }}>Pistes :</h4>
            {album.tracks?.map((track, idx) => (
              <div
                key={track.id}
                style={{
                  display: 'flex', alignItems: 'center', gap: '0.75rem',
                  padding: '0.75rem',
                  background: '#f5f5f5',
                  marginBottom: '0.5rem',
                  borderRadius: '4px',
                }}
              >
                <span style={{ color: '#999', minWidth: 20, textAlign: 'right' }}>
                  {track.position ?? idx + 1}
                </span>
                <strong style={{ flex: 1 }}>
                  {track.explicit_lyrics && (
                    <span style={{
                      background: '#FCEBEB', color: '#A32D2D',
                      fontSize: 10, fontWeight: 600, padding: '1px 5px',
                      borderRadius: 3, marginRight: 6,
                    }}>E</span>
                  )}
                  {track.title}
                </strong>
                <span style={{ color: '#999', fontSize: 13 }}>
                  {formatDuration(track.duration)}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // ---- Vue liste ----
  return (
    <div>
      <h2>💿 Albums</h2>

      {error   && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}

      {userRole === 'admin' && (
        <div className="filter-section">
          <button onClick={() => setShowForm(!showForm)} className="btn-primary">
            {showForm ? '❌ Annuler' : '➕ Créer un album'}
          </button>

          {showForm && (
            <form onSubmit={handleSubmit} style={{ marginTop: '1rem' }}>
              <div className="filter-group">
                <div className="form-group">
                  <label>Titre *</label>
                  <input
                    type="text"
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Artiste *</label>
                  <select
                    value={formData.artistId}
                    onChange={(e) => setFormData({ ...formData, artistId: e.target.value })}
                    required
                  >
                    <option value="">Sélectionner</option>
                    {artistsData?.artists?.nodes?.map((artist) => (
                      <option key={artist.id} value={artist.id}>{artist.name}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="filter-group">
                <div className="form-group">
                  <label>Date de sortie</label>
                  <input
                    type="date"
                    value={formData.release_date}
                    onChange={(e) => setFormData({ ...formData, release_date: e.target.value })}
                  />
                </div>
                <div className="form-group">
                  <label>Genre ID</label>
                  <input
                    type="number"
                    min="0"
                    value={formData.genre_id}
                    placeholder="ex: 132"
                    onChange={(e) => setFormData({ ...formData, genre_id: e.target.value })}
                  />
                </div>
                <div className="form-group">
                  <label>Label</label>
                  <input
                    type="text"
                    value={formData.label}
                    onChange={(e) => setFormData({ ...formData, label: e.target.value })}
                  />
                </div>
              </div>

              <button type="submit" className="btn-success" disabled={createLoading}>
                {createLoading ? '⏳ Création...' : '✅ Créer'}
              </button>
            </form>
          )}
        </div>
      )}

      <div className="items-grid">
        {albums.map((album) => (
          <div
            key={album.id}
            className="card"
            onClick={() => setSelectedAlbum(album.id)}
            style={{ cursor: 'pointer' }}
          >
            {album.cover_medium && (
              <img
                src={album.cover_medium}
                alt={album.title}
                style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '4px', marginBottom: '1rem' }}
                onError={(e) => { e.target.style.display = 'none'; }}
              />
            )}
            <h3>{album.title}</h3>
            <p>🎤 {album.artist?.name}</p>

            <div className="card-meta">
              {album.release_date && (
                <span>📅 {new Date(album.release_date).getFullYear()}</span>
              )}
              <span>🎵 {album.nb_tracks ?? 0} piste{album.nb_tracks > 1 ? 's' : ''}</span>
              {album.genre_id && <span>🏷️ Genre #{album.genre_id}</span>}
            </div>

            {userRole === 'admin' && (
              <div className="card-actions">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    if (window.confirm(`Supprimer "${album.title}" ?`)) {
                      deleteAlbum({ variables: { id: album.id } });
                    }
                  }}
                  className="btn-danger"
                >
                  🗑️ Supprimer
                </button>
              </div>
            )}
          </div>
        ))}
      </div>

      {albums.length === 0 && <div className="empty">📭 Aucun album</div>}

      <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', marginTop: '2rem' }}>
        <button
          onClick={() => setPage((p) => p - 1)}
          disabled={!pageInfo.hasPreviousPage}
          className="btn-secondary"
        >
          ← Précédent
        </button>
        <span style={{ alignSelf: 'center' }}>
          Page {pageInfo.currentPage} / {pageInfo.totalPages}
        </span>
        <button
          onClick={() => setPage((p) => p + 1)}
          disabled={!pageInfo.hasNextPage}
          className="btn-secondary"
        >
          Suivant →
        </button>
      </div>
    </div>
  );
}
